-- NONPRODUCTION fixture: minimal prerequisite revision schema, not a migration.
-- Existing ROS KO schema/guards are then loaded from the actual migration.
create extension if not exists pgcrypto with schema extensions;
create table public.novel_documents(id text primary key,slug text unique not null,title text not null,data jsonb not null,updated_at timestamptz not null default now());
create table public.revision_projects(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,description text,source_document_id text,owner_id uuid references auth.users(id),target_range_min int default 165000,target_range_max int default 185000,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.content_units(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.revision_projects(id),unit_type text not null check(unit_type in ('act','chapter','scene','paragraph')),source_key text not null,source_path text,original_parent_id uuid references public.content_units(id),original_position int default 0,title text,created_at timestamptz default now(),unique(project_id,source_key),unique(project_id,source_path));
create table public.paragraph_versions(id uuid primary key default gen_random_uuid(),paragraph_unit_id uuid not null references public.content_units(id),version_no int not null default 1,body_markdown text not null,body_hash text not null,base_version_id uuid references public.paragraph_versions(id),change_type text default 'import' check(change_type in ('import','rewrite','split','merge','calibration','polish','canon_normalization')),change_note text,word_count int default 0,created_by uuid references auth.users(id),created_at timestamptz default now(),unique(paragraph_unit_id,version_no));
create table public.paragraph_version_lineage(id uuid primary key default gen_random_uuid(),child_version_id uuid references public.paragraph_versions(id),parent_version_id uuid references public.paragraph_versions(id),relation_type text check(relation_type in ('rewritten_from','split_from','merged_from','adapted_from')),sequence_no int default 1,note text,created_at timestamptz default now(),unique(child_version_id,parent_version_id));
create table public.revision_snapshots(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.revision_projects(id),code text not null,name text,description text,state text default 'draft',base_snapshot_id uuid references public.revision_snapshots(id),manifest_hash text,word_count int default 0,locked_at timestamptz,locked_by uuid,created_at timestamptz default now(),updated_at timestamptz default now(),snapshot_kind text default 'formal',is_canonical boolean default true,is_current_release boolean default false,is_primary_working boolean default false);
create table public.revision_content_map(snapshot_id uuid references public.revision_snapshots(id),unit_id uuid references public.content_units(id),parent_unit_id uuid references public.content_units(id),position int not null,paragraph_version_id uuid references public.paragraph_versions(id),is_included boolean not null default true,title_override text,metadata_override jsonb,primary key(snapshot_id,unit_id));
-- Constraints additionally confirmed against production metadata (no row dump).
alter table public.revision_snapshots add constraint fixture_snapshot_kind check(snapshot_kind in ('formal','pilot','audit'));
alter table public.revision_snapshots add constraint fixture_snapshot_state check(state in ('draft','locked','archived'));
alter table public.revision_snapshots add constraint fixture_snapshot_code unique(project_id,code);
alter table public.revision_content_map add constraint fixture_map_position unique(snapshot_id,parent_unit_id,position) deferrable initially deferred;
